#!/usr/bin/env python3
# -*- coding: utf-8 -*-

"""
Restauration de la prologue de base de PONAN'S LEGACY.

- Restaure prologue.js avec la version image-based de la prologue.
- Conserve les images déjà présentes dans assets/prologue/.
- Ne télécharge, ne supprime et ne déplace aucune image.
- Crée une sauvegarde de prologue.js avant remplacement.
"""

from pathlib import Path
import base64
import shutil
import subprocess
import sys
import os

PROJECT_CANDIDATES = [
    Path("/home/paulo/ponanini"),
    Path.cwd(),
]

TARGET_NAME = "prologue.js"

SOURCE_B64 = """"""


def find_project():
    for path in PROJECT_CANDIDATES:
        if (path / TARGET_NAME).exists() or (path / "assets").exists():
            return path
    return Path.cwd()


def restore():
    project = find_project()
    target = project / TARGET_NAME
    assets = project / "assets" / "prologue"

    print("==============================================")
    print(" RESTAURATION PROLOGUE — PONAN'S LEGACY")
    print("==============================================")
    print(f"Projet : {project}")
    print()

    if not project.exists():
        print("ERREUR : dossier du projet introuvable.")
        sys.exit(1)

    if target.exists():
        backup = project / "prologue.js.bak_base"
        shutil.copy2(target, backup)
        print(f"[OK] Sauvegarde : {backup}")
    else:
        print("[INFO] prologue.js n'existait pas encore.")

    restored = base64.b64decode(SOURCE_B64).decode("utf-8")
    target.write_text(restored, encoding="utf-8")
    print(f"[OK] Prologue restaurée : {target}")

    print()
    print("Vérification des images du prologue :")
    missing = []

    for i in range(1, 12):
        image = assets / f"scene{i}.png"
        if image.exists():
            print(f"  [OK] scene{i}.png")
        else:
            print(f"  [!!] scene{i}.png MANQUANTE")
            missing.append(image)

    if not assets.exists():
        print(f"[!!] Dossier absent : {assets}")
        print("     Le script ne crée aucune image automatiquement.")

    print()
    print("Vérification JavaScript...")

    result = subprocess.run(
        ["node", "--check", str(target)],
        capture_output=True,
        text=True
    )

    if result.returncode != 0:
        print("[ERREUR] prologue.js contient une erreur de syntaxe.")
        print(result.stderr)
        sys.exit(result.returncode)

    print("[OK] Syntaxe JavaScript valide.")
    print()
    print("La prologue de base est restaurée.")
    print("Les images existantes n'ont pas été modifiées.")

    if missing:
        print()
        print("ATTENTION : certaines images sont absentes.")
        print("Le jeu cherchera exactement :")
        for image in missing:
            print(f"  - {image}")

    print()
    print("Tu peux maintenant lancer le jeu.")


if __name__ == "__main__":
    restore()
